Here’s a drop-in example for a typical Node/Express user profile API using an in-memory TTL cache.

```js
// src/cache/ttlCache.js

class TTLCache {
  constructor(defaultTtlMs = 60_000) {
    this.defaultTtlMs = defaultTtlMs;
    this.store = new Map();
  }

  get(key) {
    const entry = this.store.get(key);

    if (!entry) return null;

    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return null;
    }

    return entry.value;
  }

  set(key, value, ttlMs = this.defaultTtlMs) {
    this.store.set(key, {
      value,
      expiresAt: Date.now() + ttlMs,
    });
  }

  delete(key) {
    this.store.delete(key);
  }

  clear() {
    this.store.clear();
  }
}

module.exports = TTLCache;
```

```js
// src/cache/userProfileCache.js

const TTLCache = require('./ttlCache');

const USER_PROFILE_TTL_MS = 5 * 60 * 1000;

const userProfileCache = new TTLCache(USER_PROFILE_TTL_MS);

module.exports = userProfileCache;
```

```js
// src/routes/users.js

const express = require('express');
const router = express.Router();

const userProfileCache = require('../cache/userProfileCache');
const userService = require('../services/userService');

router.get('/:userId/profile', async (req, res, next) => {
  try {
    const { userId } = req.params;
    const cacheKey = `user-profile:${userId}`;

    const cachedProfile = userProfileCache.get(cacheKey);

    if (cachedProfile) {
      res.set('X-Cache', 'HIT');
      return res.json(cachedProfile);
    }

    const profile = await userService.getUserProfile(userId);

    if (!profile) {
      return res.status(404).json({ error: 'User not found' });
    }

    userProfileCache.set(cacheKey, profile);

    res.set('X-Cache', 'MISS');
    return res.json(profile);
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

If profiles can be updated, invalidate the cache on writes:

```js
// src/routes/users.js

router.put('/:userId/profile', async (req, res, next) => {
  try {
    const { userId } = req.params;

    const updatedProfile = await userService.updateUserProfile(userId, req.body);

    userProfileCache.delete(`user-profile:${userId}`);

    return res.json(updatedProfile);
  } catch (error) {
    next(error);
  }
});
```

For production with multiple app instances, use Redis instead of an in-memory `Map`.
